package core

import (
	"testing"

	"github.com/KogenAI/kogen-executor/executor"
)

func usageCost(f float64) *float64 { return &f }

func checkUsageInt(t *testing.T, field string, got, want *int) {
	t.Helper()
	switch {
	case got == nil && want == nil:
	case got == nil || want == nil:
		t.Errorf("%s = %v, want %v", field, got, want)
	case *got != *want:
		t.Errorf("%s = %d, want %d", field, *got, *want)
	}
}

func checkUsageCost(t *testing.T, got, want *float64) {
	t.Helper()
	switch {
	case got == nil && want == nil:
	case got == nil || want == nil:
		t.Errorf("CostUSD = %v, want %v", got, want)
	case *got != *want:
		t.Errorf("CostUSD = %v, want %v", *got, *want)
	}
}

func TestExecutorUsagePlusAddsCompleteRound(t *testing.T) {
	total := ExecutorUsage{Input: Count(1), Cached: Count(2), Output: Count(3), Reasoning: Count(4), CostUSD: usageCost(0.5)}
	round := executor.Usage{Input: Count(10), Cached: Count(20), Output: Count(30), Reasoning: Count(40), CostUSD: usageCost(1.25)}
	got := total.Plus(round, false)
	checkUsageInt(t, "Input", got.Input, Count(11))
	checkUsageInt(t, "Cached", got.Cached, Count(22))
	checkUsageInt(t, "Output", got.Output, Count(33))
	checkUsageInt(t, "Reasoning", got.Reasoning, Count(44))
	checkUsageCost(t, got.CostUSD, usageCost(1.75))
}

func TestExecutorUsagePlusCarriesRoundSource(t *testing.T) {
	total := ExecutorUsage{Source: "old-source"}
	got := total.Plus(executor.Usage{Source: "new-source"}, false)
	if got.Source != "new-source" {
		t.Errorf("Source = %q, want the round's source", got.Source)
	}
}

func TestExecutorUsagePlusMissingValuesStayUnknown(t *testing.T) {
	total := ExecutorUsage{Cached: Count(5), Output: Count(7), CostUSD: usageCost(0.5)}
	round := executor.Usage{Input: Count(3), Output: Count(11)}
	got := total.Plus(round, false)
	checkUsageInt(t, "Input", got.Input, nil)
	checkUsageInt(t, "Cached", got.Cached, nil)
	checkUsageInt(t, "Output", got.Output, Count(18))
	checkUsageInt(t, "Reasoning", got.Reasoning, nil)
	checkUsageCost(t, got.CostUSD, nil)

	total = ExecutorUsage{Output: Count(1)}
	round = executor.Usage{Output: Count(2), CostUSD: usageCost(1.25)}
	got = total.Plus(round, false)
	checkUsageInt(t, "Output", got.Output, Count(3))
	checkUsageCost(t, got.CostUSD, nil)
}

func TestExecutorUsagePlusFirstRoundUsesItsOwnState(t *testing.T) {
	got := ExecutorUsage{}.Plus(executor.Usage{State: executor.UsageComplete}, true)
	if got.State != executor.UsageComplete {
		t.Errorf("State = %q, want %q", got.State, executor.UsageComplete)
	}
}

func TestExecutorUsagePlusEqualStatesAreRetained(t *testing.T) {
	total := ExecutorUsage{State: executor.UsageComplete}
	got := total.Plus(executor.Usage{State: executor.UsageComplete}, false)
	if got.State != executor.UsageComplete {
		t.Errorf("State = %q, want %q", got.State, executor.UsageComplete)
	}
}

func TestExecutorUsagePlusDifferingStatesBecomePartial(t *testing.T) {
	total := ExecutorUsage{State: executor.UsageComplete}
	got := total.Plus(executor.Usage{State: executor.UsageUnknown}, false)
	if got.State != executor.UsagePartial {
		t.Errorf("State = %q, want %q", got.State, executor.UsagePartial)
	}
}

func TestExecutorUsagePlusEmptyRoundStateIsUnknown(t *testing.T) {
	got := ExecutorUsage{State: executor.UsageUnknown}.Plus(executor.Usage{}, false)
	if got.State != executor.UsageUnknown {
		t.Errorf("State = %q, want %q", got.State, executor.UsageUnknown)
	}
}

